mkitem!{mkimpl!{# [unstable (feature = "error_reporter" , issue = "90172")] impl < E > fmt :: Debug for Report < E > where Report < E > : fmt :: Display , { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { fmt :: Display :: fmt (self , f) } }}}
mkitem!{mkstruct!{# [doc = " Wrapper type for indenting the inner source."] struct Indented < 'a , D > { inner : & 'a mut D , }}}
mkitem!{mkimpl!{impl < T > Write for Indented < '_ , T > where T : Write , { fn write_str (& mut self , s : & str) -> fmt :: Result { for (i , line) in s . split ('\n') . enumerate () { if i > 0 { self . inner . write_char ('\n') ? ; self . inner . write_str ("      ") ? ; } self . inner . write_str (line) ? ; } Ok (()) } }}}